Based on my analysis of the littlefs codebase, I can see the block allocator uses a lookahead buffer (bitmap) to track free blocks. The `lfs_alloc` function scans this bitmap to find a free block, with wear leveling achieved by scanning from the last position. Here's the implementation:

```cpp
    while (true) {
        // scan our lookahead buffer for free blocks
        while (lfs->lookahead.next < lfs->lookahead.size) {
            if (!(lfs->lookahead.buffer[lfs->lookahead.next / 8]
                    & (1U << (lfs->lookahead.next % 8)))) {
                // found a free block
                *block = (lfs->lookahead.start + lfs->lookahead.next)
                        % lfs->block_count;

                // eagerly find next free block to maximize how many blocks
                // lfs_alloc_ckpoint makes available for scanning
                while (true) {
                    lfs->lookahead.next += 1;
                    lfs->lookahead.ckpoint -= 1;

                    if (lfs->lookahead.next >= lfs->lookahead.size
                            || lfs->lookahead.ckpoint == 0) {
                        break;
                    }

                    if (!(lfs->lookahead.buffer[lfs->lookahead.next / 8]
                            & (1U << (lfs->lookahead.next % 8)))) {
                        break;
                    }
                }

                return 0;
            }

            lfs->lookahead.next += 1;
            lfs->lookahead.ckpoint -= 1;
        }

        // out of blocks in current lookahead buffer, try to scan for more
        int err = lfs_alloc_scan(lfs);
        if (err) {
            return err;
        }

        // if we still have no blocks, we're out of space
        if (lfs->lookahead.size == 0) {
            return LFS_ERR_NOSPC;
        }
    }
